      result += renderNodes(truthy(readPath(node.path, context)) ? node.body : node.alternate, context);
    } else {
      const items = readPath(node.path, context);
      if (Array.isArray(items) && items.length) {
        for (let index = 0; index < items.length; index++) result += renderNodes(node.body, { root: context.root, value: items[index], index });
      } else result += renderNodes(node.alternate, context);
    }
  }
  return result;
}

/** Render a Mini Template string using a root data object. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { root: data, value: data });
}
import { render } from "./engine";

const [templateFile, dataFile] = Bun.argv.slice(2);
if (!templateFile || !dataFile || Bun.argv.slice(2).length !== 2) {
  console.error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  process.exit(1);
}

try {
  const [template, json] = await Promise.all([Bun.file(templateFile).text(), Bun.file(dataFile).text()]);
  process.stdout.write(render(template, JSON.parse(json)));
} catch (cause) {
  console.error(cause instanceof Error ? cause.message : String(cause));
  process.exit(1);
}
import { expect, test } from "bun:test";
import { render } from "../src/engine";

test("interpolates escaped and raw values", () => {
  expect(render("{{value}}|{{{value}}}|{{missing}}", { value: `<&>\"'` })).toBe("&lt;&amp;&gt;&quot;&#39;|<&>\"'|");
});
test("conditionals support nesting and falsey values", () => {
  expect(render("{{#if user}}{{#if user.admin}}A{{else}}U{{/if}}{{else}}N{{/if}}", { user: { admin: false } })).toBe("U");
  expect(render("{{#if value}}yes{{else}}no{{/if}}", { value: [] })).toBe("no");
});
test("each supports context, root fallback, nesting, and else", () => {
  expect(render("{{#each rows}}{{title}}:{{@index}}={{this}};{{/each}}", { title: "T", rows: ["a", "b"] })).toBe("T:0=a;T:1=b;");
  expect(render("{{#each rows}}{{#each this}}{{@index}}={{this}}/{{/each}}{{/each}}", { rows: [[1, 2]] })).toBe("0=1/1=2/");
  expect(render("{{#each rows}}x{{else}}empty{{/each}}", { rows: [] })).toBe("empty");
});
test("comments and whitespace are preserved", () => {
  expect(render(" a {{! ignored }}\n{{x}} ", { x: "b" })).toBe(" a \nb ");
});
test("reports invalid structures and non-scalar values", () => {
  expect(() => render("{{else}}", {})).toThrow("line 1, column 1");
  expect(() => render("{{#if x}}{{/each}}", {})).toThrow("Mismatched");
  expect(() => render("{{#if x}}", {})).toThrow("Unclosed");
  expect(() => render("{{x}}", { x: {} })).toThrow("Cannot render object");
});
# Mini Template

A small, dependency-free TypeScript template renderer for Bun.

```ts
import { render } from "./src/engine";

render("Hello, {{user.name}}!", { user: { name: "Ada" } });
```

It supports escaped `{{paths}}`, raw `{{{paths}}}`, nested `#if` and `#each`
blocks (including `{{this}}` and `{{@index}}`), comments, and `{{else}}`.
Missing values render empty; invalid block structure and object/function
interpolations throw location-aware errors.

Render files from the command line:

```sh
bun run src/cli.ts template.html data.json
```

Run the self-tests with `bun test`.
